// SPDX-License-Identifier: MIT
pragma solidity ^0.8.0;


import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
 
contract LandRegistry is ReentrancyGuard {
    // State Variables
    address public admin;
    uint public landsTotal;
    uint public usersTotal;
    uint public requestCount;
    uint public transferTotal;

    // Mappings
    mapping(uint => Land) public lands;
    mapping(uint => bool) public landExists;
    mapping(address => User) public users;
    mapping(address => bool) public userExists;
    mapping(address => uint[]) public userLands;
    mapping(uint => Request) public requests;
    mapping(uint => bool) public requestExists;
    mapping(address => uint[]) public receivedRequests;
    mapping(address => uint[]) public sentRequests;
    mapping(uint => LandHistory[]) public landHistories;

    // Enums
    enum UserRole { Admin, Seller, Buyer }
    enum RequestStatus { Requested, Accepted, Rejected, Completed }

    // Structs
    struct User {
        address id;
        string fullName;
        string profileHash;
        string email;
        string phoneNumber;
        bool isLoggedIn;
        string addressLocation;
        UserRole role;
        bool isVerified;
        bool isBanned;
        uint256 dateJoined;
    }

    struct Land {
        uint id;
        string title;
        string documentHash;
        uint price;
        string locationAddress;
        string landAddress;
        address payable postedBy;
        string detail;
        uint256 postedDate;
        bool isVerified;
        uint area;
    }

    struct Request {
        uint id;
        address sellerId;
        address buyerId;
        uint landId;
        bool isPaymentDone;
        RequestStatus status;
    }

    struct LandHistory {
        address userAddress;
        uint256 occupiedDate;
    }

    struct LandHistory2 {
        User user;
        uint256 occupiedDate;
    }

    // Events
    event UserRegistered(address indexed userAddress, string fullName, UserRole role);
    event UserLoggedIn(address indexed userAddress);
    event UserLoggedOut(address indexed userAddress);
    event LandCreated(uint indexed landId, address indexed postedBy);
    event RequestSent(uint indexed requestId, address indexed buyer, uint indexed landId);
    event RequestStatusUpdated(uint indexed requestId, RequestStatus status);
    event PaymentMade(uint indexed requestId, uint amount);
    event LandTransferred(uint indexed landId, address indexed newOwner);

    // Errors
    error Unauthorized();
    error UserNotFound();
    error LandNotFound();
    error RequestNotFound();
    error InvalidCredentials();
    error InsufficientPayment();

    // Modifiers
    modifier onlyAdmin() {
        require(users[msg.sender].role == UserRole.Admin, "Unauthorized: Admin only");
        _;
    }

    modifier onlySeller() {
        require(users[msg.sender].role == UserRole.Seller, "Unauthorized: Seller only");
        _;
    }

    modifier onlyBuyer() {
        require(users[msg.sender].role == UserRole.Buyer, "Unauthorized: Buyer only");
        _;
    }

    modifier userMustExist(address userAddress) {
        if (!userExists[userAddress]) revert UserNotFound();
        _;
    }

    modifier landMustExist(uint landId) {
        if (!landExists[landId]) revert LandNotFound();
        _;
    }

    modifier requestMustExist(uint requestId) {
        if (!requestExists[requestId]) revert RequestNotFound();
        _;
    }

    // Constructor
    constructor() {
        admin = msg.sender;
        _registerUser(
            admin,
            "Admin",
            "https://example.com/admin.jpg",
            "admin@admin.com",
            "+11111111111111111",
            "Addis Ababa",
            UserRole.Admin
        );
    }

    // User Functions
    function registerUser(
        string memory _fullName,
        string memory _profileHash,
        string memory _email,
        string memory _phoneNumber,
        string memory _addressLocation,
        UserRole _role
    ) external {
        require(!userExists[msg.sender], "User already exists");

        _registerUser(
            msg.sender,
            _fullName,
            _profileHash,
            _email,
            _phoneNumber,
            _addressLocation,
            _role
        );
    }

    function _registerUser(
        address _userAddress,
        string memory _fullName,
        string memory _profileHash,
        string memory _email,
        string memory _phoneNumber,
        string memory _addressLocation,
        UserRole _role
    ) internal {
        users[_userAddress] = User({
            id: _userAddress,
            fullName: _fullName,
            profileHash: _profileHash,
            email: _email,
            phoneNumber: _phoneNumber,
            isLoggedIn: false,
            addressLocation: _addressLocation,
            role: _role,
            isVerified: false,
            isBanned: false,
            dateJoined: block.timestamp
        });
        userExists[_userAddress] = true;
        usersTotal++;

        emit UserRegistered(_userAddress, _fullName, _role);
    }

    function login() external userMustExist(msg.sender) {
        users[msg.sender].isLoggedIn = true;
        emit UserLoggedIn(msg.sender);
    }

    function logout() external userMustExist(msg.sender) {
        users[msg.sender].isLoggedIn = false;
        emit UserLoggedOut(msg.sender);
    }

    // Land Functions
    function createLand(
        string memory _title,
        string memory _documentHash,
        uint _price,
        string memory _locationAddress,
        string memory _landAddress,
        string memory _detail,
        uint _area
    ) external onlySeller returns (uint) {
        landsTotal++;
        lands[landsTotal] = Land({
            id: landsTotal,
            title: _title,
            documentHash: _documentHash,
            price: _price,
            locationAddress: _locationAddress,
            landAddress: _landAddress,
            postedBy: payable(msg.sender),
            detail: _detail,
            postedDate: block.timestamp,
            isVerified: false,
            area: _area
        });
        landExists[landsTotal] = true;
        userLands[msg.sender].push(landsTotal);

        emit LandCreated(landsTotal, msg.sender);
        return landsTotal;
    }

    // Request Functions
    function sendRequest(uint _landId) external onlyBuyer landMustExist(_landId) returns (uint) {
        requestCount++;
        requests[requestCount] = Request({
            id: requestCount,
            sellerId: lands[_landId].postedBy,
            buyerId: msg.sender,
            landId: _landId,
            isPaymentDone: false,
            status: RequestStatus.Requested
        });
        requestExists[requestCount] = true;
        receivedRequests[lands[_landId].postedBy].push(requestCount);
        sentRequests[msg.sender].push(requestCount);

        emit RequestSent(requestCount, msg.sender, _landId);
        return requestCount;
    }

    function acceptRequest(uint _requestId) external requestMustExist(_requestId) {
        require(requests[_requestId].sellerId == msg.sender, "Unauthorized: Only seller can accept");
        requests[_requestId].status = RequestStatus.Accepted;
        emit RequestStatusUpdated(_requestId, RequestStatus.Accepted);
    }

    function rejectRequest(uint _requestId) external requestMustExist(_requestId) {
        require(requests[_requestId].sellerId == msg.sender, "Unauthorized: Only seller can reject");
        requests[_requestId].status = RequestStatus.Rejected;
        emit RequestStatusUpdated(_requestId, RequestStatus.Rejected);
    }

    // Transfer Functions
    function transferLandTitle(uint _requestId) external requestMustExist(_requestId) {
        require(requests[_requestId].status == RequestStatus.Accepted, "Request not accepted");
        require(requests[_requestId].isPaymentDone, "Payment not done");

        uint landId = requests[_requestId].landId;
        address buyerId = requests[_requestId].buyerId;

        lands[landId].postedBy = payable(buyerId);
        LandHistory memory history = LandHistory(buyerId, block.timestamp);
        landHistories[landId].push(history);

        emit LandTransferred(landId, buyerId);
    }

    // Land History Functions
    function getLandHistory(uint landId) external view landMustExist(landId) returns (LandHistory2[] memory) {
        LandHistory[] memory history = landHistories[landId];
        LandHistory2[] memory formattedHistory = new LandHistory2[](history.length);

        for (uint i = 0; i < history.length; i++) {
            formattedHistory[i] = LandHistory2({
                user: users[history[i].userAddress],
                occupiedDate: history[i].occupiedDate
            });
        }

        return formattedHistory;
    }

    // Payment Functions
    function makePayment(uint _requestId) external payable onlyBuyer requestMustExist(_requestId) nonReentrant {
        Request storage request = requests[_requestId];
        require(request.status == RequestStatus.Accepted, "Request not accepted");
        require(!request.isPaymentDone, "Payment already done");
        require(msg.value >= lands[request.landId].price, "Insufficient payment");

        request.isPaymentDone = true;
        (bool success, ) = lands[request.landId].postedBy.call{value: msg.value}("");
        require(success, "Payment failed");

        emit PaymentMade(_requestId, msg.value);
    }
}

contracts/Lock.sol.content:
// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.9;

// Uncomment this line to use console.log
// import "hardhat/console.sol";

contract Lock {
    uint public unlockTime;
    address payable public owner;

    event Withdrawal(uint amount, uint when);

    constructor(uint _unlockTime) payable {
        require(
            block.timestamp < _unlockTime,
            "Unlock time should be in the future"
        );

        unlockTime = _unlockTime;
        owner = payable(msg.sender);
    }

    function withdraw() public {
        // Uncomment this line, and the import of "hardhat/console.sol", to print a log in your terminal
        // console.log("Unlock time is %o and block timestamp is %o", unlockTime, block.timestamp);

        require(block.timestamp >= unlockTime, "You can't withdraw yet");
        require(msg.sender == owner, "You aren't the owner");

        emit Withdrawal(address(this).balance, block.timestamp);

        owner.transfer(address(this).balance);
    }
}

